// Guarda la última lectura en memoria (para el chat) y la pasa a la tabla (para el reporte)
const sd = $getWorkflowStaticData('global');
let datos;
try {
  datos = JSON.parse($json.message);
} catch (e) {
  return [];
}
sd.ultimo = datos;
sd.recibido = new Date().toISOString();
return [{ json: {
  temperatura: datos.temperatura,
  humedad: datos.humedad,
  indice_uv: datos.indice_uv,
  voltaje_mv: datos.voltaje_mv,
} }];

// Mensaje del usuario en Telegram
const mensaje = $('Telegram Trigger').first().json.message.text || '';

// Última lectura guardada por la rama MQTT
const sd = $getWorkflowStaticData('global');
const sensores = sd.ultimo || null;
const minutos = sd.recibido
  ? Math.round((Date.now() - new Date(sd.recibido).getTime()) / 60000)
  : null;

const datos = sensores
  ? [
      '- Temperatura: ' + (sensores.temperatura ?? 'sin dato') + ' °C',
      '- Humedad relativa: ' + (sensores.humedad ?? 'sin dato') + ' %',
      '- Índice UV: ' + sensores.indice_uv + ' (' + sensores.categoria_uv + ')',
      '- Voltaje del sensor UV: ' + sensores.voltaje_mv + ' mV',
      '- Antigüedad de la lectura: ' + (minutos === null ? 'desconocida' : 'hace ' + minutos + ' min'),
    ].join('\n')
  : 'No hay datos disponibles de la estación todavía.';

const systemPrompt =
  'Eres un ingeniero agrónomo asistente que responde por Telegram a un agricultor. ' +
  'Cruza SIEMPRE su pregunta con las condiciones climáticas actuales de la estación de campo que se te entregan. ' +
  'Usa solo esos datos; si falta alguno o no hay datos, dilo claramente y no inventes valores. ' +
  'Si un dato aparece como 0 o N/A porque el sensor no está instalado, ignóralo y no lo menciones. ' +
  'Responde en español, de forma clara y breve (máximo 150 palabras), con recomendaciones prácticas. ' +
  'Referencias: temperatura ideal general 18-28 °C, humedad relativa ideal 50-70 %, ' +
  'UV >= 6 (alto) implica riesgo de estrés en plantas jóvenes y para el personal en campo.';

const userPrompt =
  '## Condiciones actuales de la estación\n' + datos +
  '\n\n## Mensaje del agricultor\n' + mensaje;

const body = {
  model: 'accounts/fireworks/models/gpt-oss-120b',
  temperature: 0.3,
  max_tokens: 2000,
  reasoning_effort: 'low',
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: userPrompt },
  ],
};

return [{ json: { body } }];

// Historial leído de la tabla (puede venir vacío)
const filas = $input.all()
  .map(i => i.json)
  .filter(r => r.temperatura !== undefined && r.temperatura !== null)
  .sort((a, b) => new Date(a.createdAt) - new Date(b.createdAt));

const serie = (campo) => filas.map(r => Number(r[campo])).filter(v => !isNaN(v));
const resumen = (nombre, v, unidad) => {
  if (!v.length) return '- ' + nombre + ': sin datos';
  const min = Math.min(...v), max = Math.max(...v);
  const prom = v.reduce((a, b) => a + b, 0) / v.length;
  const delta = v[v.length - 1] - v[0];
  const tend = Math.abs(delta) < 0.5 ? 'estable' : (delta > 0 ? 'subiendo' : 'bajando');
  return '- ' + nombre + ': mín ' + min.toFixed(1) + ', máx ' + max.toFixed(1) +
         ', promedio ' + prom.toFixed(1) + ' ' + unidad + ', tendencia ' + tend;
};

const uv = serie('indice_uv');
const hayUv = uv.some(v => v > 0);

const hora = (r) => new Date(r.createdAt).toLocaleTimeString('es-ES', { hour: '2-digit', minute: '2-digit' });
const periodo = filas.length
  ? 'de ' + new Date(filas[0].createdAt).toLocaleString('es-ES') + ' a ' + new Date(filas[filas.length - 1].createdAt).toLocaleString('es-ES')
  : 'sin datos';

const lineas = [
  '- Periodo: ' + periodo,
  '- Lecturas: ' + filas.length + ' (una cada ~10 min)',
  resumen('Temperatura', serie('temperatura'), '°C'),
  resumen('Humedad relativa', serie('humedad'), '%'),
];
if (hayUv) lineas.push(resumen('Índice UV', uv, ''));

const systemPrompt =
  'Eres un ingeniero agrónomo que redacta reportes por Telegram para un agricultor. ' +
  'Usa SOLO las estadísticas entregadas; no inventes valores. Si no hay lecturas, dilo. ' +
  'Escribe en español, en texto plano SIN markdown (sin asteriscos ni #), con emojis y guiones. ' +
  'Estructura: 1) Resumen del periodo, 2) Temperatura, 3) Humedad, 4) Riesgos detectados, 5) Recomendaciones prácticas. ' +
  'Máximo 250 palabras. Referencias: temperatura ideal 18-28 °C, humedad relativa ideal 50-70 %.';

const body = {
  model: 'accounts/fireworks/models/gpt-oss-120b',
  temperature: 0.3,
  max_tokens: 2500,
  reasoning_effort: 'low',
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: '## Estadísticas de la estación\n' + lineas.join('\n') + '\n\nGenera el reporte.' },
  ],
};

// Gráfica con QuickChart (máx. 48 puntos para que la URL no sea enorme)
const paso = Math.max(1, Math.ceil(filas.length / 48));
const muestra = filas.filter((_, i) => i % paso === 0);
const config = {
  type: 'line',
  data: {
    labels: muestra.map(hora),
    datasets: [
      { label: 'Temperatura (°C)', data: muestra.map(r => Number(r.temperatura)), borderColor: '#db6635', fill: false },
      { label: 'Humedad (%)', data: muestra.map(r => Number(r.humedad)), borderColor: '#3182ab', fill: false },
    ],
  },
  options: { title: { display: true, text: 'AGRIOT - Temperatura y humedad' } },
};
const chartUrl = 'https://quickchart.io/chart?w=700&h=350&bkg=white&c=' + encodeURIComponent(JSON.stringify(config));

return [{ json: { body, chartUrl } }];
